import { TelemetryEventSchema } from '../../telemetryEvents';

/**
 * Server API request/response DTO schemas.
 *
 * This module only depends on `zod` and other side-effect-free schema modules, so it can
 * be imported without touching the user configuration directory.
 */

// GET /api/remote-health
export const RemoteHealthResponseSchema = z.object({
  status: z.string(),
  message: z.string(),
});
export type RemoteHealthResponse = z.infer<typeof RemoteHealthResponseSchema>;

// GET /health
export const HealthResponseSchema = z.object({
  status: z.literal('OK'),
  version: z.string().min(1),
});
export type HealthResponse = z.infer<typeof HealthResponseSchema>;

// GET /api/results
export const GetResultsQuerySchema = z.object({
  datasetId: z.string().optional(),
  type: z.enum(['redteam', 'eval']).optional(),
  // Query params arrive as strings. Only the exact string 'true' should coerce to true;
  // everything else (including 'false', '1', 'yes', and omitted) resolves to false.
  includeProviders: z
    .string()
    .optional()
    .transform((value) => value === 'true'),
});
export type GetResultsQuery = z.infer<typeof GetResultsQuerySchema>;

// GET /api/prompts/:sha256hash
export const PromptHashParamsSchema = z.object({
  sha256hash: z
    .string()
    .regex(/^[a-f0-9]{64}$/i, 'sha256hash must be a 64-character hexadecimal (SHA-256) string'),
});
export type PromptHashParams = z.infer<typeof PromptHashParamsSchema>;

// GET /api/history
export const HistoryQuerySchema = z.object({
  tagName: z.string().optional(),
  tagValue: z.string().optional(),
  description: z.string().optional(),
});
export type HistoryQuery = z.infer<typeof HistoryQuerySchema>;

// GET /api/results/share/check-domain
export const CheckShareDomainQuerySchema = z.object({
  id: z
    .string()
    .min(1)
    .refine((value) => value !== 'undefined', { message: 'id is required' }),
});
export type CheckShareDomainQuery = z.infer<typeof CheckShareDomainQuerySchema>;

export const CheckShareDomainResponseSchema = z.object({
  domain: z.string(),
  isCloudEnabled: z.boolean(),
});
export type CheckShareDomainResponse = z.infer<typeof CheckShareDomainResponseSchema>;

// POST /api/results/share
export const ShareRequestSchema = z
  .object({
    id: z.string().min(1),
  })
  .passthrough();
export type ShareRequest = z.infer<typeof ShareRequestSchema>;

// POST /api/dataset/generate
/**
 * A prompt may be provided as a raw string or as an object with a `raw` field. String
 * prompts are normalized to `{ raw, label }` (label defaults to the raw string). Object
 * prompts without a `label` get `label` set to their `raw` value; extra fields are
 * preserved.
 */
export const DatasetGeneratePromptSchema = z
  .union([z.string(), z.object({ raw: z.string(), label: z.string().optional() }).passthrough()])
  .transform((prompt) =>
    typeof prompt === 'string'
      ? { raw: prompt, label: prompt }
      : { ...prompt, label: prompt.label ?? prompt.raw },
  );

export const DatasetGenerateRequestSchema = z.object({
  prompts: z.array(DatasetGeneratePromptSchema).min(1),
  tests: z
    .array(z.unknown().refine((value) => value != null, { message: 'test case cannot be null' }))
    .optional()
    .default([]),
});
export type DatasetGenerateRequest = z.infer<typeof DatasetGenerateRequestSchema>;

// POST /api/telemetry
export { TelemetryEventSchema };

/** Grouped schemas for server-side validation. */
export const ServerSchemas = {
  RemoteHealth: {
    Response: RemoteHealthResponseSchema,
  },
  Health: {
    Response: HealthResponseSchema,
  },
  GetResults: {
    Query: GetResultsQuerySchema,
  },
  PromptHash: {
    Params: PromptHashParamsSchema,
  },
  History: {
    Query: HistoryQuerySchema,
  },
  CheckShareDomain: {
    Query: CheckShareDomainQuerySchema,
    Response: CheckShareDomainResponseSchema,
  },
  Share: {
    Request: ShareRequestSchema,
  },
  DatasetGenerate: {
    Request: DatasetGenerateRequestSchema,
  },
  Telemetry: {
    Request: TelemetryEventSchema,
  },
} as const;
